def uart_frame(byte, parity=None):
    """The bits of one UART frame: start bit, 8 data bits LSB first, optional parity, one stop bit."""
    data = [(byte >> i) & 1 for i in range(8)]
    bits = [0] + data
    if parity == "even":
        bits.append(sum(data) % 2)            # makes the total number of 1s even
    elif parity == "odd":
        bits.append(1 - sum(data) % 2)        # makes the total number of 1s odd
    return bits + [1]

